CREATE DATABASE IF NOT EXISTS AfyaCare CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE AfyaCare;
CREATE TABLE patients (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(20) NOT NULL, password VARCHAR(255) NOT NULL, is_verified TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE email_otps (id INT AUTO_INCREMENT PRIMARY KEY, patient_id INT NOT NULL UNIQUE, otp_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, attempts INT NOT NULL DEFAULT 0, last_sent_at DATETIME NOT NULL, FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
